using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
namespace Experiments;
public static class BundleStore
{
 public const string Schema="lm-experiment/1";public const long FileBudget=2*1024*1024;
 public static BundleResult Write(string parent,Dictionary<string,(byte[] Bytes,string Representation)> payloads,Outcome outcome)
 {
  string root=Path.GetFullPath(parent);Directory.CreateDirectory(root);RejectLink(root);
  if(payloads.Count>20||payloads.Values.Any(v=>v.Bytes.Length>FileBudget))throw new InvalidDataException("Run exceeds artifact budgets.");
  string id=Guid.NewGuid().ToString("N"),stage=Path.Combine(root,".pending-"+id),destination=Path.Combine(root,id);Directory.CreateDirectory(stage);
  try{var files=new List<Artifact>();foreach(var pair in payloads.OrderBy(p=>p.Key,StringComparer.Ordinal)){CheckName(pair.Key);WriteNew(Path.Combine(stage,pair.Key),pair.Value.Bytes);files.Add(new(pair.Key,pair.Value.Bytes.Length,Data.Digest(pair.Value.Bytes),pair.Value.Representation));}
   var manifest=new Manifest(Schema,id,DateTimeOffset.UtcNow,"LM Experiment Workbench0.1",files.ToArray());byte[] bytes=Data.Bytes(manifest);string digest=Data.Digest(bytes);WriteNew(Path.Combine(stage,"manifest.json"),bytes);WriteNew(Path.Combine(stage,"manifest.sha256"),Encoding.ASCII.GetBytes(digest+"  manifest.json\n"));Directory.Move(stage,destination);return new(destination,id,digest,outcome);
  }catch{if(Directory.Exists(stage))Directory.Delete(stage,true);throw;}
 }
 public static Verification Verify(string directory,string? independentlyRetainedDigest=null)
 {
  var issues=new List<string>();string? digest=null;
  try{string root=Path.GetFullPath(directory);RejectLink(root);byte[] bytes=Read(root,"manifest.json",65536);digest=Data.Digest(bytes);string anchor=Encoding.ASCII.GetString(Read(root,"manifest.sha256",256)).Trim();if(anchor!=digest+"  manifest.json")issues.Add("Adjacent manifest digest differs.");if(independentlyRetainedDigest is not null&&!string.Equals(digest,independentlyRetainedDigest,StringComparison.OrdinalIgnoreCase))issues.Add("Independently retained digest differs.");
   var manifest=JsonSerializer.Deserialize<Manifest>(bytes,Data.Json)??throw new InvalidDataException("Null manifest.");if(manifest.Schema!=Schema||manifest.Artifacts.Length is <2 or >20)throw new InvalidDataException("Unsupported schema/artifact count.");var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase){"manifest.json","manifest.sha256"};
   foreach(var file in manifest.Artifacts){CheckName(file.Name);if(!names.Add(file.Name)||file.Bytes<0||file.Bytes>FileBudget||!Regex.IsMatch(file.Sha256,"^[a-f0-9]{64}$"))throw new InvalidDataException("Invalid artifact declaration.");var body=Read(root,file.Name,FileBudget);if(body.LongLength!=file.Bytes||Data.Digest(body)!=file.Sha256)issues.Add("Artifact differs: "+file.Name);}
   if(!names.Contains("spec.json")||!names.Contains("outcome.json"))issues.Add("Missing required spec/outcome roles.");foreach(string entry in Directory.EnumerateFileSystemEntries(root))if(!names.Contains(Path.GetFileName(entry)))issues.Add("Uncommitted entry: "+Path.GetFileName(entry));
  }catch(Exception e)when(e is IOException or InvalidDataException or UnauthorizedAccessException or ArgumentException or JsonException or NullReferenceException){issues.Add(e.Message);}
  return new(issues.Count==0,digest,issues.ToArray());
 }
 public static T ReadArtifact<T>(string directory,string name){CheckName(name);if(!Verify(directory).Valid)throw new InvalidDataException("Bundle failed integrity verification.");return JsonSerializer.Deserialize<T>(Read(Path.GetFullPath(directory),name,FileBudget),Data.Json)??throw new InvalidDataException("Null artifact.");}
 public static void Export(string directory,string newDestination){if(!Verify(directory).Valid)throw new InvalidDataException("Cannot export invalid bundle.");if(Directory.Exists(newDestination)||File.Exists(newDestination))throw new IOException("Export destination must not exist.");var manifest=JsonSerializer.Deserialize<Manifest>(Read(directory,"manifest.json",65536),Data.Json)!;Directory.CreateDirectory(newDestination);foreach(string name in manifest.Artifacts.Select(a=>a.Name).Concat(["manifest.json","manifest.sha256"]))WriteNew(Path.Combine(newDestination,name),Read(directory,name,FileBudget));}
 public static Comparison Compare(string a,string b){if(!Verify(a).Valid||!Verify(b).Valid)return new(false,false,[],[],"Both bundles must pass integrity checks.");var sa=ReadArtifact<ExperimentSpec>(a,"spec.json");var sb=ReadArtifact<ExperimentSpec>(b,"spec.json");var changes=Changes(sa,sb);var oa=ReadArtifact<Outcome>(a,"outcome.json");var ob=ReadArtifact<Outcome>(b,"outcome.json");var observed=new List<string>();if(oa.State!=ob.State)observed.Add($"Outcome: {oa.State} → {ob.State}");foreach(var check in ob.LoadChecks)if(oa.LoadChecks.FirstOrDefault(c=>c.Key==check.Key)?.Applied!=check.Applied)observed.Add("Server-reported load config changed: "+check.Key);if(oa.Identity.ResponseInstance!=ob.Identity.ResponseInstance)observed.Add("Response instance identifier changed.");return new(true,changes.Length==1,changes,observed.ToArray(),"Requested-factor accounting only. Unknown file/runtime identities, backend state, stochastic inference and uncontrolled factors prevent causal/reproducibility proof.");}
 public static FactorChange[] Changes(ExperimentSpec a,ExperimentSpec b){Dictionary<string,string> Flatten(ExperimentSpec s){var root=JsonSerializer.SerializeToNode(s,Data.Json)!.AsObject();root.Remove("backendLabel");root["integrationsJson"]=JsonNode.Parse(s.IntegrationsJson);var result=new Dictionary<string,string>();void Walk(string path,JsonNode? node){if(node is JsonObject o&&o.Count>0){foreach(var k in o)Walk(path==""?k.Key:path+"."+k.Key,k.Value);}else if(node is JsonArray array&&array.Count>0){for(int i=0;i<array.Count;i++)Walk(path+"["+i+"]",array[i]);}else result[path]=node?.ToJsonString()??"null";}Walk("",root);return result;}var aa=Flatten(a);var bb=Flatten(b);return aa.Keys.Union(bb.Keys).Order(StringComparer.Ordinal).Where(k=>aa.GetValueOrDefault(k)!=bb.GetValueOrDefault(k)).Select(k=>new FactorChange(k,aa.GetValueOrDefault(k)??"<absent>",bb.GetValueOrDefault(k)??"<absent>")).ToArray();}
 public static ReplayDecision ReplayGuard(string directory,ExperimentSpec proposed){var valid=Verify(directory);if(!valid.Valid)return new(false,valid.Issues,[]);var original=ReadArtifact<ExperimentSpec>(directory,"spec.json");var result=ReadArtifact<Outcome>(directory,"outcome.json");var blockers=new List<string>();if(result.State!="completed")blockers.Add("Previous run did not complete successfully.");if(Changes(original,Data.Validate(proposed)).Length!=0)blockers.Add("Requested factors changed; this is a new experiment, not exact configuration replay.");if(result.LoadChecks.Length!=3||result.LoadChecks.Any(c=>c.Verdict!="match"))blockers.Add("Requested load settings were missing or differed in server echo.");if(JsonNode.Parse(original.IntegrationsJson)!.AsArray().Count!=0)blockers.Add("Automatic replay of plugin/tool integrations is blocked to avoid repeated side effects.");return new(blockers.Count==0,blockers.ToArray(),["Configuration replay only, not identical-output replay.","Model-file SHA256 and runtime-engine version remain unknown through this API contract.","Fresh load/chat can change backend state; sampling and hardware determinism are not established."]);}
 static void CheckName(string name){if(!Regex.IsMatch(name,"^[a-z0-9][a-z0-9._-]{0,79}$")||name.Contains("..",StringComparison.Ordinal)||name is "manifest.json" or "manifest.sha256")throw new InvalidDataException("Unsafe artifact name.");}
 static byte[] Read(string directory,string name,long budget){string path=Path.Combine(directory,name);var info=new FileInfo(path);if(!info.Exists||(info.Attributes&FileAttributes.ReparsePoint)!=0||info.Length>budget)throw new InvalidDataException("Missing/linked/oversized file: "+name);return File.ReadAllBytes(path);}
 static void RejectLink(string path){var info=new DirectoryInfo(path);if(!info.Exists||(info.Attributes&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Missing or linked bundle directory.");}
 static void WriteNew(string path,byte[] bytes){using var file=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None);file.Write(bytes);file.Flush(true);}
}
